 "content": "from collections import Counter, deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            result.append((color, cells))
    return result


def _corner(cells):
    rs, cs = [r for r, c in cells], [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    pts = set(cells)
    forms = {
        "tl": {(r0, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)},
        "tr": {(r0, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)},
        "bl": {(r1, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)},
        "br": {(r1, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)},
    }
    for orient, shape in forms.items():
        if r0 < r1 and c0 < c1 and pts == shape:
            return orient, (r0, r1, c0, c1)
    return None


def transform(grid):
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid)
    ls = [(color, cells, _corner(cells)) for color, cells in comps
          if color != bg and _corner(cells) is not None]
    if not ls:
        return out
    marker, mcells, found = max(ls, key=lambda x: len(x[1]))
    orient, (r0, r1, c0, c1) = found
    # For a top-right edge L, select the nearest separate object in the
    # upper-left sector, opposite the two arms' corner.
    if orient == "bl":
        elbow = (r1, c0)
        candidates = []
        for color, cells in comps:
            if color in (bg, marker):
                continue
            if all(r < elbow[0] and c < elbow[1] for r, c in cells):
                dist = min(abs(r - elbow[0]) + abs(c - elbow[1]) for r, c in cells)
                candidates.append((dist, cells))
        if candidates:
            cells = min(candidates, key=lambda x: x[0])[1]
            for r, c in cells:
                out[r][c] = marker
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
